data = json.dumps({'app_id': app_id, 'app_secret': app_secret}).encode('utf-8')
req = urllib.request.Request(url, data=data, headers={'Content-Type': 'application/json'})
with urllib.request.urlopen(req, timeout=10) as resp:
    token = json.loads(resp.read()).get('tenant_access_token')

doc_token = 'HrlGdwuJvoEIcDxXbFhcYmMtnrb'

def add_children(children, retry=2):
    for attempt in range(retry):
        add_url = f'https://open.feishu.cn/open-apis/docx/v1/documents/{doc_token}/blocks/{doc_token}/children'
        payload = json.dumps({"children": children}).encode('utf-8')
        req = urllib.request.Request(add_url, data=payload, headers={
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {token}'
        })
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result = json.loads(resp.read())
                if result.get('code') == 0:
                    return result
                else:
                    print(f"  API error: {result}")
                    time.sleep(1)
        except HTTPError as e:
            err_body = e.read().decode()
            print(f"  HTTP {e.code}: {err_body[:200]}")
            time.sleep(2)
    return {"code": -1, "msg": "failed after retries"}

def h1(content): 
    return {"block_type": 3, "heading1": {"elements": [{"text_run": {"content": content, "text_element_style": {}}}], "style": {}}}
def h2(content): 
    return {"block_type": 4, "heading2": {"elements": [{"text_run": {"content": content, "text_element_style": {}}}], "style": {}}}
def h3(content): 
    return {"block_type": 5, "heading3": {"elements": [{"text_run": {"content": content, "text_element_style": {}}}], "style": {}}}
def p(content): 
    return {"block_type": 2, "text": {"elements": [{"text_run": {"content": content, "text_element_style": {}}}], "style": {}}}
