    return {"block_type": 12, "bullet": {"elements": [{"text_run": {"content": content, "text_element_style": {}}}], "style": {"indent_level": 1}}}
def ordered(content): 
    return {"block_type": 13, "ordered": {"elements": [{"text_run": {"content": content, "text_element_style": {}}}], "style": {"indent_level": 1}}}
def divider(): 
    return {"block_type": 22}

# Send all batches with delay
batches = [
    [divider(), h1("二、大盘 Role 体系"), h2("2.1 基础 Role 分群矩阵"), p("人生阶段（6个）× 城市等级（5个）= 30 个基础 Role")],
