    [ordered("适婚时期：年龄 ∈ {25-29, 30-34} AND 婚姻状态 = 未婚"), ordered("事业成熟期：年龄 ∈ {30-54} AND 工龄 ≥ 5年 且 非未婚"), ordered("求职时期：年龄 ∈ {18-29} AND 工作状况 = 待业"), ordered("老年黄金期：年龄 ≥ 55 OR 工作状况 = 退休")],
